#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")" # cd into the script dir

# no folding doesn't symlink entire folder, only individual files. otherwise files generated by the app are pushed to the dir/repo.
# target home dir, include options/flags/params (-nv for testing only), all sub-dirs.
stow --no-folding --target "$HOME" "$@" */ 
